const dictionary=new Map(pairs);
let language='en';try{if(localStorage.getItem('hipos.language')==='fil')language='fil';}catch{}
const originals=new WeakMap(),attributes=new WeakMap();
export const getLanguage=()=>language;
export function translate(text){
  if(language==='en')return text;
  const trimmed=text.trim(),translated=dictionary.get(trimmed);
  if(translated)return text.replace(trimmed,translated);
  if(trimmed.startsWith('· '))return text.replace(trimmed,'· '+translate(trimmed.slice(2)));
  if(trimmed.includes(' · '))return text.replace(trimmed,trimmed.split(' · ').map(translate).join(' · '));
  const importPrefix='Nothing was imported. Ask the student to show the QR from My reports, or copy its complete transfer text.';
  if(trimmed.startsWith(importPrefix+' '))return translate(importPrefix)+' '+translate(trimmed.slice(importPrefix.length+1));
  if(trimmed.startsWith('Status for '))return 'Katayuan para sa '+trimmed.slice(11);
  const patterns=[[/^Caught (\d+) of (\d+) compostable scraps$/,m=>`Nahuli ${m[1]} sa ${m[2]} na tirang maaaring i-compost`],[/^You caught (\d+) of (\d+) compostable scraps\.$/,m=>`Nakasalo ka ng ${m[1]} sa ${m[2]} na tirang maaaring i-compost.`],[/^Item (\d+) of (\d+)$/,m=>`Aytem ${m[1]} sa ${m[2]}`],[/^You sorted (\d+) of (\d+) right\.$/,m=>`Tama ang ${m[1]} sa ${m[2]} na na-uri mo.`],[/^Treats shared: (\d+)$/,m=>`Mga treat na naibahagi: ${m[1]}`],[/^(\d+) of (\d+) stickers collected\. Stickers stay yours once you earn them\.$/,m=>`${m[1]} sa ${m[2]} sticker ang nakolekta. Sa iyo na ang mga sticker kapag nakuha mo.`],[/^New sticker: (.+)!$/,m=>`Bagong sticker: ${m[1].split(', ').map(translate).join(', ')}!`],[/^New buddy extra unlocked: (.+)\. Open My buddy to try it\.$/,m=>`Bagong dagdag para sa buddy: ${m[1].split(', ').map(translate).join(', ')}. Buksan ang Aking buddy para subukan.`],[/^(\d+) day streak$/,m=>`${m[1]} araw na tuloy-tuloy`],[/^Best: (\d+) days?$/,m=>`Pinakamahaba: ${m[1]} araw`],[/^(\d) of 7 days active$/,m=>`${m[1]} sa 7 araw ang aktibo`],[/^Showing (\d+) of (\d+) reports?$/,m=>`Ipinapakita ang ${m[1]} sa ${m[2]} ulat`],[/^(\d+) items?$/,m=>`${m[1]} aytem`],[/^(\d+) of (\d+) items$/,m=>`${m[1]} sa ${m[2]} aytem`],[/^Restored (\d+) reports?\.(?: (\d+) already on this device\.)?(?: (\d+) could not be read\.)?$/,m=>`Naibalik ang ${m[1]} ulat.${m[2]?` ${m[2]} ang nasa device na ito na.`:''}${m[3]?` ${m[3]} ang hindi mabasa.`:''}`],[/^(\d) of 3 actions completed today( · Ready for today)?$/,m=>`${m[1]} sa 3 gawain ang natapos ngayon${m[2]?' · Handa na para ngayon':''}`],[/^Question (\d) of 3$/,m=>`Tanong ${m[1]} sa 3`],[/^(\d) of 3 correct$/,m=>`${m[1]} sa 3 ang tama`],[/^Saved reports \((\d+)\)$/,m=>`Mga naka-save na ulat (${m[1]})`]];
  for(const [regex,format] of patterns){const match=trimmed.match(regex);if(match)return text.replace(trimmed,format(match));}
  return text;
}
export function translateUI(root=document.body){
  observer?.disconnect();
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let node;while((node=walker.nextNode())){
    if(node.parentElement.closest('script,style,textarea,.report-description,[data-no-translate],#language option'))continue;
    const previous=originals.get(node),source=previous&&node.textContent===previous.output?previous.source:node.textContent;
    if(node.parentElement.tagName==='OPTION'&&!node.parentElement.hasAttribute('value'))node.parentElement.value=node.textContent;
    const output=translate(source);originals.set(node,{source,output});if(node.textContent!==output)node.textContent=output;
  }
  for(const el of root.querySelectorAll('[aria-label],[placeholder]')){
    if(el.closest('[data-no-translate]'))continue;
    const cached=attributes.get(el)||{};
    for(const name of ['aria-label','placeholder']){if(!el.hasAttribute(name))continue;const current=el.getAttribute(name),old=cached[name],source=old&&old.output===current?old.source:current,output=translate(source);cached[name]={source,output};if(output!==current)el.setAttribute(name,output);}
    attributes.set(el,cached);
  }
  document.documentElement.lang=language;
  observer?.observe(document.body,{childList:true,subtree:true,characterData:true});
}
let observer;
export function initLanguage(){
  const select=document.querySelector('#language');select.value=language;
  observer=new MutationObserver(()=>translateUI());
  select.addEventListener('change',()=>{
    const next=select.value;
    try{localStorage.setItem('hipos.language',next);}catch{select.value=language;document.querySelector('#notice').textContent=language==='fil'?'Hindi na-save ang wika. Subukan muli.':'Could not save language. Try again.';return;}
    language=next;translateUI();
  });translateUI();
}
